/* @lc app=leetcode id=2097 lang=kotlin */ class Solution { fun validArrangement(pairs: Array<IntArray>): Array<IntArray> = HashMap<Int, java.util.ArrayDeque<Int>>().also { out -> pairs.forEach { out.getOrPut(it[0]) { java.util.ArrayDeque() }.add(it[1]) } }.let { out -> HashMap<Int, Int>().also { deg -> pairs.forEach { listOf(it[0] to 1, it[1] to -1).forEach { (v, d) -> deg.merge(v, d) { a, b -> a + b } } } }.let { deg -> java.util.ArrayDeque<Int>().also { it.addFirst(deg.entries.firstOrNull { e -> e.value == 1 }?.key ?: pairs[0][0]) }.let { st -> generateSequence { st.peekFirst()?.let { v -> out[v]?.pollFirst()?.let { st.addFirst(it).let { -1 } } ?: st.pollFirst() } }.filter { it >= 0 }.toList().reversed().zipWithNext { a, b -> intArrayOf(a, b) }.toTypedArray() } } } }